3	export async function inTransaction<T>(pool: pg.Pool, work: (client: pg.PoolClient) => Promise<T>): Promise<T> {
4	  const client = await pool.connect();
5	  try {
6	    await client.query('begin');
7	    const result = await work(client);
8	    await client.query('commit');
9	    return result;
10	  } catch (error) {
11	    await client.query('rollback');
12	    throw error;
13	  } finally {
14	    client.release();
15	  }
